"use client";

import { useCallback, useEffect, useRef, useState } from "react";
import { useTranslations } from "next-intl";
import { TextInput } from "@/app/_components/TextInput";
import type { ProcessEvent, SeedFile } from "@/app/features/sub_dev/DevTypes";

// Live Work Surface (moonshot E) — an in-product editor over the materialized seed.
// As the candidate works, it records OBSERVED process events (which files they
// open, edit, and decision-log entries) and flushes them + the file tree to the
// session. The engine then grades the judgment we WATCHED, not a reconstructed git
// log. We observe process artifacts only — never keystrokes or the screen.

const DECISIONS_FILE = "DECISIONS.md";
const FLUSH_MS = 8000;
const EDIT_DEBOUNCE_MS = 600;
// Local-first safety net (see DECISIONS.md "loss modes"): a tab close, refresh, or
// crash wipes React state instantly, and the server flush interval (FLUSH_MS) means
// up to 8s of edits — or an entire offline stretch — can still be in flight when that
// happens. We mirror the editable tree + identity fields + not-yet-acked events to
// localStorage on every change, keyed per token, and restore it before the seed on
// mount. This is deliberately synchronous and network-independent: it protects work
// even through the multi-minute offline periods flaky hotel/train wifi produces,
// where a server round-trip cannot be relied on at all.
const storageKeyFor = (token: string) => `devcase:livework:${token}`;

export function LiveWorkSurface({ token, seedFiles, note }: { token: string; seedFiles: SeedFile[]; note: string | null }) {
  const t = useTranslations("devApply.workSurface");
  const [files, setFiles] = useState<SeedFile[]>(() => seedFiles.map((f) => ({ ...f })));
  const [activePath, setActivePath] = useState<string>(seedFiles[0]?.path ?? "");
  const [status, setStatus] = useState<"idle" | "submitting" | "submitted" | "error">("idle");
  const [restoredNotice, setRestoredNotice] = useState(false);
  // Sync indicator — surfaces the local-first / flaky-connection story to the
  // candidate instead of leaving them guessing whether their work is safe.
  const [syncState, setSyncState] = useState<"saved" | "pending" | "offline">("saved");

  // Identity (UAT M9): the live-work surface is the SOLE submit path for workspace
  // cases now, so it collects who to reach — a winning evaluation with no address
  // is an unreachable candidate. Labels reuse the repo-form's `devApply` keys.
  const tApply = useTranslations("devApply");
  const [name, setName] = useState("");
  const [contact, setContact] = useState("");
  const contactValid = /\S+@\S+\.\S+/.test(contact.trim());
  const canSubmit = name.trim().length > 0 && contactValid && status !== "submitting";

  const sessionIdRef = useRef<string | null>(null);
  const startingRef = useRef(false);
  const submittingRef = useRef(false);
  const pendingRef = useRef<ProcessEvent[]>([]);
  const filesRef = useRef(files);
  const nameRef = useRef(name);
  const contactRef = useRef(contact);
  const hydratedRef = useRef(false);
  useEffect(() => {
    // Keep the ref current for the flush callback without re-creating the interval
    // on every keystroke. Synced in an effect (not during render) per react-hooks/refs.
    filesRef.current = files;
  }, [files]);
  useEffect(() => {
    nameRef.current = name;
  }, [name]);
  useEffect(() => {
    contactRef.current = contact;
  }, [contact]);
  const editTimer = useRef<ReturnType<typeof setTimeout> | null>(null);

  // Restore-then-persist to localStorage, network-independent so it survives an
  // offline stretch just as well as a plain reload. Read once on mount (before any
  // network call), then re-written after every local mutation.
  const persistLocal = useCallback(() => {
    if (typeof window === "undefined") return;
    try {
      window.localStorage.setItem(
        storageKeyFor(token),
        JSON.stringify({
          v: 1,
          savedAt: Date.now(),
          sessionId: sessionIdRef.current,
          files: filesRef.current,
          pending: pendingRef.current,
          name: nameRef.current,
          contact: contactRef.current,
        })
      );
    } catch {
      // best-effort (private mode / quota) — the in-memory state is still correct,
      // this only weakens the reload guarantee.
    }
  }, [token]);

  useEffect(() => {
    if (typeof window === "undefined") return;
    try {
      const raw = window.localStorage.getItem(storageKeyFor(token));
      if (raw) {
        const saved = JSON.parse(raw) as {
          sessionId?: string | null;
          files?: SeedFile[];
          pending?: ProcessEvent[];
          name?: string;
          contact?: string;
        };
        if (Array.isArray(saved.files) && saved.files.length > 0) {
          setFiles(saved.files);
          setActivePath((prev) => (saved.files!.some((f) => f.path === prev) ? prev : saved.files![0].path));
          setRestoredNotice(true);
        }
        if (saved.sessionId) sessionIdRef.current = saved.sessionId;
        if (Array.isArray(saved.pending) && saved.pending.length > 0) pendingRef.current = saved.pending;
        if (typeof saved.name === "string" && saved.name) setName(saved.name);
        if (typeof saved.contact === "string" && saved.contact) setContact(saved.contact);
      }
    } catch {
      // corrupt/blocked storage — fall back to the pristine seed, no worse than before.
    } finally {
      hydratedRef.current = true;
    }
    // token is stable for the component's lifetime (route param); intentionally run once.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  // Lazily mint the session on first interaction — never orphan a session for a
  // visitor who only reads the brief.
  const ensureSession = useCallback(async (): Promise<string | null> => {
    if (sessionIdRef.current) return sessionIdRef.current;
    if (startingRef.current) return null;
    startingRef.current = true;
    try {
      const r = await fetch("/api/devcase/session", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ token }),
      });
      if (!r.ok) return null;
      const data = (await r.json()) as { sessionId?: string };
      sessionIdRef.current = data.sessionId ?? null;
      return sessionIdRef.current;
    } catch {
      return null;
    } finally {
      startingRef.current = false;
    }
  }, [token]);

  const record = useCallback(
    (kind: ProcessEvent["kind"], path?: string, size?: number) => {
      pendingRef.current.push({ t: Date.now(), kind, path, size });
      persistLocal();
      void ensureSession();
    },
    [ensureSession, persistLocal]
  );

  const flush = useCallback(
    async (opts?: { submit?: boolean }) => {
      // Offline-aware (post mid-flight update): don't even attempt the round-trip
      // when the browser already knows it's offline — the batch stays buffered
      // (and is already durable in localStorage via persistLocal) until connectivity
      // returns, instead of racing a fetch that's certain to fail on flaky wifi.
      if (typeof navigator !== "undefined" && navigator.onLine === false) {
        setSyncState(pendingRef.current.length > 0 ? "offline" : "offline");
        return;
      }
      const sid = await ensureSession();
      if (!sid) {
        setSyncState(pendingRef.current.length > 0 ? "offline" : "saved");
        return;
      }
      const batch = pendingRef.current;
      if (batch.length === 0) {
        setSyncState("saved");
        return;
      }
      setSyncState("pending");
      pendingRef.current = [];
      try {
        const r = await fetch(`/api/devcase/session/${sid}`, {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ events: batch, files: filesRef.current }),
          keepalive: opts?.submit,
        });
        if (!r.ok) throw new Error("flush failed");
        setSyncState("saved");
      } catch {
        // Re-buffer so an unsent batch isn't lost (best-effort). The batch is also
        // already sitting in localStorage from the record()/edit-time persistLocal
        // calls, so a tab close mid-outage doesn't lose it either.
        pendingRef.current = batch.concat(pendingRef.current);
        setSyncState("offline");
      } finally {
        persistLocal();
      }
    },
    [ensureSession, persistLocal]
  );

  useEffect(() => {
    const iv = setInterval(() => void flush(), FLUSH_MS);
    // Retry promptly the moment the browser regains connectivity, rather than
    // waiting out the rest of the poll interval — the difference matters most
    // right after a multi-minute hotel/train wifi drop.
    const onOnline = () => void flush();
    const onOffline = () => setSyncState("offline");
    window.addEventListener("online", onOnline);
    window.addEventListener("offline", onOffline);
    // Best-effort last flush on the way out; localStorage (already current) is the
    // real safety net if this doesn't land.
    const onHide = () => {
      if (document.visibilityState === "hidden") void flush({ submit: false });
    };
    document.addEventListener("visibilitychange", onHide);
    window.addEventListener("pagehide", onHide);
    return () => {
      clearInterval(iv);
      if (editTimer.current) clearTimeout(editTimer.current);
      window.removeEventListener("online", onOnline);
      window.removeEventListener("offline", onOffline);
      document.removeEventListener("visibilitychange", onHide);
      window.removeEventListener("pagehide", onHide);
    };
  }, [flush]);

  function selectFile(path: string) {
    if (path === activePath) return;
    setActivePath(path);
    record("open", path);
  }

  function onEdit(path: string, contents: string) {
    setFiles((prev) => {
      const next = prev.map((f) => (f.path === path ? { ...f, contents } : f));
      filesRef.current = next; // persistLocal below reads the ref; keep it current sync
      return next;
    });
    persistLocal(); // every keystroke lands in localStorage immediately — the debounce
    // below only governs how often we tell the *server* (and the process log), not
    // how often the browser itself is durable.
    if (editTimer.current) clearTimeout(editTimer.current);
    editTimer.current = setTimeout(() => {
      record(path.endsWith(DECISIONS_FILE) ? "decision_log" : "edit", path);
    }, EDIT_DEBOUNCE_MS);
  }

  async function submit() {
    // Synchronous in-flight guard: setStatus is async, so a fast double Enter/click
    // could dispatch two POSTs before the button visibly disables. The ref flips
    // immediately, so a second call is a no-op until this one settles; reset in the
    // finally so an error is retryable (on success the submit button is gone anyway).
    if (submittingRef.current || !canSubmit) return;
    submittingRef.current = true;
    setStatus("submitting");
    record("submit", activePath);
    try {
      await flush({ submit: true });
      const sid = sessionIdRef.current;
      if (!sid) {
        setStatus("error");
        return;
      }
      const r = await fetch(`/api/devcase/session/${sid}/submit`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ candidate: name.trim(), contact: contact.trim() }),
      }).catch(() => null);
      const ok = !!(r && r.ok);
      setStatus(ok ? "submitted" : "error");
      if (ok && typeof window !== "undefined") {
        // Only clear the local safety net once the server has confirmed the
        // submission — an error leaves it in place so a retry doesn't start blank.
        try {
          window.localStorage.removeItem(storageKeyFor(token));
        } catch {
          // ignore
        }
      }
    } finally {
      submittingRef.current = false;
    }
  }

  const active = files.find((f) => f.path === activePath) ?? files[0];

  if (status === "submitted") {
    return (
      <section className="mt-6 rounded-lg border border-emerald-200 bg-emerald-50 p-5">
        <h2 className="font-serif text-h3 text-emerald-900">{t("submittedTitle")}</h2>
        <p className="mt-1 text-sm text-emerald-800">{t("submitted")}</p>
      </section>
    );
  }

  return (
    <section className="mt-6 rounded-lg border border-stone-200 bg-white p-5 shadow-panel">
      <h2 className="font-serif text-h3 text-ink">{t("heading")}</h2>
      <p className="mt-1 max-w-prose text-sm text-steel">{t("intro")}</p>
      {note ? <p className="mt-2 text-xs text-stone-400">{note}</p> : null}
      {restoredNotice ? (
        <p className="mt-2 rounded-md bg-limewash/40 px-2 py-1 text-xs text-ink">
          Restored your in-progress work from this browser.
        </p>
      ) : null}
      {/* Local-first sync indicator (added for the flaky-connection update): the
          candidate's work is safe on THIS device the moment they type — this line
          only reports whether it has also reached the server yet, so a hotel-wifi
          drop reads as "syncing", never as data loss. */}
      <p className="mt-2 text-xs text-stone-400" aria-live="polite">
        {syncState === "saved" && "Saved."}
        {syncState === "pending" && "Saving…"}
        {syncState === "offline" && "Offline — your work is saved on this device and will sync automatically."}
      </p>

      <div className="mt-4 grid gap-3 sm:grid-cols-[180px_1fr]">
        <ul className="space-y-1">
          {files.map((f) => (
            <li key={f.path}>
              <button
                type="button"
                onClick={() => selectFile(f.path)}
                className={`w-full truncate rounded px-2 py-1 text-left font-mono text-xs ${
                  f.path === active?.path ? "bg-stone-900 text-white" : "text-ink hover:bg-stone-100"
                }`}
                title={f.path}
              >
                {f.path}
              </button>
            </li>
          ))}
        </ul>
        <textarea
          value={active?.contents ?? ""}
          onChange={(e) => active && onEdit(active.path, e.target.value)}
          onPaste={(e) => {
            // Record paste MAGNITUDE (char count) only — not the content. A single
            // large bulk paste into the watched editor is the in-product
            // paste-from-LLM tell the authenticity scorer now penalizes.
            const n = (e.clipboardData?.getData("text") ?? "").length;
            if (active && n > 0) record("paste", active.path, n);
          }}
          spellCheck={false}
          className="focus-ring h-80 w-full resize-y rounded-md border border-stone-200 bg-stone-50 p-3 font-mono text-xs leading-relaxed text-ink caret-coral"
          aria-label={active?.path ?? "editor"}
        />
      </div>

      <div className="mt-4 grid gap-3 sm:grid-cols-2">
        <label className="block text-sm font-medium text-ink">
          {tApply("fieldName")} <span className="text-coral">*</span>
          <TextInput
            value={name}
            onChange={(e) => {
              setName(e.target.value);
              nameRef.current = e.target.value;
              persistLocal();
            }}
            className="mt-1"
          />
        </label>
        <label className="block text-sm font-medium text-ink">
          {tApply("fieldContact")} <span className="text-coral">*</span>
          <TextInput
            type="email"
            value={contact}
            onChange={(e) => {
              setContact(e.target.value);
              contactRef.current = e.target.value;
              persistLocal();
            }}
            placeholder={tApply("fieldContactPlaceholder")}
            className="mt-1"
          />
          <span className="mt-1 block text-xs font-normal text-steel">{tApply("fieldContactHint")}</span>
        </label>
      </div>
      <div className="mt-4 flex items-center gap-3">
        <button
          type="button"
          onClick={submit}
          disabled={!canSubmit}
          className="rounded-md bg-stone-900 px-4 py-2 text-sm font-medium text-white hover:bg-stone-800 disabled:cursor-not-allowed disabled:opacity-60"
        >
          {status === "submitting" ? t("submitting") : t("submit")}
        </button>
        {status === "error" ? <span className="text-sm text-red-700">{t("error")}</span> : null}
      </div>
    </section>
  );
}
